<?php
declare(strict_types=1);defined('_JEXEC')or die;use Joomla\CMS\HTML\HTMLHelper;use Joomla\CMS\Language\Text;use Joomla\CMS\Router\Route;
?>
<?php if(isset($summary['error'])):?><div class="alert alert-info mb-0"><?php echo Text::_($summary['error']);?></div><?php else:$club=$summary['club'];?>
<article class="card"><div class="card-body"><div class="d-flex gap-3 align-items-start"><?php if((bool)$params->get('show_logo',1)&&$club->logo):?><img src="<?php echo htmlspecialchars((string)$club->logo,ENT_QUOTES,'UTF-8');?>" alt="" class="img-fluid" width="80" height="80" loading="lazy"><?php else:?><span class="icon-shield fs-2 text-body-secondary" aria-hidden="true"></span><?php endif;?><div class="flex-grow-1"><h3 class="h5 mb-1"><a class="stretched-link text-decoration-none" href="<?php echo Route::_('index.php?option=com_joomleague&view=club&club_id='.(int)$club->id);?>"><?php echo htmlspecialchars((string)$club->name,ENT_QUOTES,'UTF-8');?></a></h3><?php if($club->short_name):?><div class="text-body-secondary"><?php echo htmlspecialchars((string)$club->short_name,ENT_QUOTES,'UTF-8');?></div><?php endif;?><div class="d-flex flex-wrap gap-2 mt-2"><span class="badge text-bg-light border"><?php echo Text::sprintf('MOD_JOOMLEAGUE_CLUB_TEAM_COUNT',count($summary['teams']));?></span><?php if($club->country_code):?><span class="badge text-bg-secondary"><?php echo htmlspecialchars((string)$club->country_code,ENT_QUOTES,'UTF-8');?></span><?php endif;?></div></div></div>
<?php if((bool)$params->get('show_teams',1)&&$summary['teams']!==[]):?><h4 class="h6 mt-3"><?php echo Text::_('COM_JOOMLEAGUE_CLUB_TEAMS_TITLE');?></h4><div class="list-group list-group-flush position-relative z-2"><?php foreach($summary['teams']as$team):?><a class="list-group-item list-group-item-action px-0" href="<?php echo Route::_('index.php?option=com_joomleague&view=team&team_id='.(int)$team->id);?>"><?php echo htmlspecialchars((string)$team->name,ENT_QUOTES,'UTF-8');?></a><?php endforeach;?></div><?php endif;?>
<?php if((bool)$params->get('show_events',1)&&$summary['events']!==[]):?><h4 class="h6 mt-3"><?php echo Text::_('MOD_JOOMLEAGUE_CLUB_UPCOMING');?></h4><div class="list-group list-group-flush position-relative z-2"><?php foreach($summary['events']as$event):?><a class="list-group-item list-group-item-action px-0" href="<?php echo Route::_('index.php?option=com_joomleague&view=eventreport&event_id='.(int)$event['id']);?>"><small class="d-block text-body-secondary"><?php echo HTMLHelper::_('date',$event['scheduled_start'],Text::_('DATE_FORMAT_LC2'),'UTC');?></small><span><?php echo htmlspecialchars(implode(' · ',array_column($event['participants'],'name')),ENT_QUOTES,'UTF-8');?></span></a><?php endforeach;?></div><?php endif;?></div></article><?php endif;?>
